# Count connected components of 3 in each row (horizontally adjacent only)
grid = [
    [0, 0, 0, 3, 1, 0, 3, 3, 3],
    [0, 3, 3, 0, 1, 0, 3, 3, 0],
    [3, 0, 3, 0, 1, 0, 3, 0, 3],
    [3, 3, 0, 0, 1, 0, 3, 3, 3]
]

def count_components(row):
    if not row:
        return 0
    components = []
    current = []
    for val in row:
        if val == 3:
            current.append(val)
        else:
            if current:
                components.append(len(current))
                current = []
    if current:
        components.append(len(current))
    return len(components)  # number of components

output = []
for i, row in enumerate(grid):
    comps = count_components(row)
    # Output: 3 if >= 2 components, 0 if 1 component
    out = 3 if comps >= 2 else 0
    print(f"Row {i}: {[0]*9}, row = {row}, components = {comps}, output = {out}")
    output.append(out)

print(f"Final output grid: {[output]}")

# Count components separately on left and right of the separator
