    [3, 0, 3, 0, 1, 0, 3, 0, 3],
    [3, 3, 0, 0, 1, 0, 3, 3, 3]
]

# Separator is at column 4 (all 1s)
# Left: cols 0-3, Right: cols 5-8

def count_components(row_slice):
    if not row_slice:
        return 0
    components = []
    current = []
    for val in row_slice:
        if val == 3:
            current.append(val)
        else:
            if current:
                components.append(1)
                current = []
    if current:
        components.append(1)
    return len(components)

for i, row in enumerate(grid):
    left = row[:4]  # cols 0-3
    right = row[5:]  # cols 5-8

    left_comps = count_components(left)
    right_comps = count_components(right)

    print(f"Row {i}: left={left_comps}, right={right_comps}")

